const input = $input.first().json.body;
const pharmacies = $input.item.json;

if (!input || !input.patientTelegramChatId) {
  return [{ json: { skipped: true, reason: 'No patientTelegramChatId' } }];
}

const chatId = input.patientTelegramChatId;
const prescriptionId = input.id;
const token = "8644047281:AAHywXMMM9zpDThyBj_FOgme46RZi_GhzRk";

const pharmacyList = Array.isArray(pharmacies) ? pharmacies : (pharmacies.data || pharmacies.results || []);

const keyboard = [];
let row = [];
for (const pharm of pharmacyList) {
  row.push({
    text: pharm.pharmacyName,
    callback_data: 'pick:' + prescriptionId + ':' + pharm.id
  });
  if (row.length === 2) {
    keyboard.push(row);
    row = [];
  }
}
if (row.length > 0) keyboard.push(row);

const text = '\uD83C\uDFE5 *Nouvelle ordonnance médicale* \u2013 N\u00B0 ' + prescriptionId + '\n\nBonjour,\n\nUne ordonnance électronique vient d\u2019\u00EAtre établie à votre nom par votre médecin traitant.\n\nVeuillez sélectionner la pharmacie de votre choix ci-dessous pour sa préparation :';

return [{ json: {
  chatId,
  prescriptionId,
  token,
  text,
  keyboard
} }];
